using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System.IO;using System.Collections.Generic;using System.Text.RegularExpressions;using System.Globalization;
public static class CoastClearance {
 public static void Run(){EditorSceneManager.OpenScene(CoastAuthored.Scene);GameObject.Find("Explorer").SetActive(false);Physics.SyncTransforms();var rows=new List<string>{"sample,x,y,z,obstacle,obstacle_height"};int i=0;foreach(Match m in Regex.Matches(File.ReadAllText("ArtSource/Lighthouse_Authored/route.json"),@"\[\s*([-\d.Ee]+),\s*([-\d.Ee]+),\s*([-\d.Ee]+)\s*\]")){var p=new Vector3(float.Parse(m.Groups[1].Value,CultureInfo.InvariantCulture),float.Parse(m.Groups[2].Value,CultureInfo.InvariantCulture),float.Parse(m.Groups[3].Value,CultureInfo.InvariantCulture));if(Physics.Raycast(p+Vector3.up*3,Vector3.down,out var h,4)&&h.point.y>p.y+.35f)rows.Add(i+","+p.x+","+p.y+","+p.z+","+h.collider.name+","+h.point.y);i++;}File.WriteAllLines("Docs/Lighthouse_Authored/ROUTE_OBSTACLES.csv",rows);}
}
